changeSet.sql:
CREATE OR ALTER PROCEDURE [dbo].[GetScoreHistoryByObject]
@assetUid uniqueidentifier, @scoreType int AS begin declare @date date = getutcdate()
select EffectiveDate as [EffectiveDate], [EndDate] as [EndDate], cast(Value * 100 as int) as Score, ScoreType from metrics.Score where AssetUid = @assetUid and EffectiveDate <= @date and ScoreType = @scoreType union select cast(@date as date) as [EffectiveDate], null as [EndDate], cast(Value * 100 as int) as Score, ScoreType from metrics.Score S inner join ( select max(EffectiveDate) as EffectiveDate from metrics.Score where AssetUid = @assetUid and EffectiveDate <= @date and ScoreType = @scoreType ) M on M.EffectiveDate = S.EffectiveDate and S.AssetUid = @assetUid and ScoreType = @scoreType end

changeSet.rollback:
CREATE OR ALTER PROCEDURE [dbo].[GetScoreHistoryByObject]
@assetUid uniqueidentifier, @scoreType int AS begin declare @date date = getutcdate()
select EffectiveDate as [Date], cast(Value * 100 as int) as Score, ScoreType from metrics.Score where AssetUid = @assetUid and EffectiveDate <= @date and ScoreType = @scoreType union select cast(@date as date) as [Date], cast(Value * 100 as int) as Score, ScoreType from metrics.Score S inner join ( select max(EffectiveDate) as EffectiveDate from metrics.Score where AssetUid = @assetUid and EffectiveDate <= @date and ScoreType = @scoreType ) M on M.EffectiveDate = S.EffectiveDate and S.AssetUid = @assetUid and ScoreType = @scoreType end
